/**
 * Round 5 (state `lesion`): a MOCK FLAIR derived from the 1 mm MNI152 T1w
 * template with SYNTHETIC white-matter lesions, generated by
 * `tools/design/segmentation_flair_assets.py`. Lesion rows come from the 3D
 * mask here (26-connected components, `workflowRules.components26`), not
 * from the generator's table, so the list and the image cannot disagree.
 */

import raw from '@/modules/segmentation/__design__/assets/lesions.json';
import { components26, rowsOfComponents, type LesionRow, type Voxel3 } from '@/modules/segmentation/components/shared/workflowRules';
import type { LabelVoxel, Plane, SliceImage } from '@/modules/segmentation/components/shared/types';

const PNG_URLS = import.meta.glob('./assets/*_flair.png', { eager: true, import: 'default', query: '?url' }) as Record<string, string>;

interface RawImage {
  file: string;
  cols: number;
  rows: number;
  plane: string;
  index: number;
}

function image(name: 'ax_flair' | 'cor_flair' | 'sag_flair'): SliceImage {
  const r = (raw.images as Record<string, RawImage>)[name];
  return {
    key: name,
    url: PNG_URLS[`./assets/${r.file}`] ?? r.file,
    plane: r.plane as Plane,
    index: r.index,
    contrast: 'FLAIR',
    viewOnly: false,
    cols: r.cols,
    rows: r.rows,
  };
}

export type LesionLocation = 'periventricular' | 'deep' | 'juxtacortical';

export interface Lesion extends LesionRow {
  location: LesionLocation;
  side: 'L' | 'R';
  reviewed: boolean;
}

const MASK: Voxel3[] = (raw.mask3d as number[][]).map((v) => [v[0], v[1], v[2]] as const);
const COMPS = components26(MASK);
const META = raw.lesions as Array<{ seed: number[]; location: string }>;
const ORIGIN = raw.grid.origin as number[];
const [, NY, NZ] = raw.grid.dims as number[];

/** The lesion being edited (row id) and the ones already reviewed (mock). */
const CURRENT = 1;
const REVIEWED = new Set([2, 3]);

const ROWS: Lesion[] = rowsOfComponents(COMPS).map((r, i) => {
  const meta = META.find((m) => COMPS[i].some((v) => v[0] === m.seed[0] && v[1] === m.seed[1] && v[2] === m.seed[2]));
  return {
    ...r,
    location: (meta?.location ?? 'deep') as LesionLocation,
    side: r.centre[0] + ORIGIN[0] < 0 ? 'L' : 'R',
    reviewed: REVIEWED.has(r.id),
  };
});

const labels = { ax: [] as LabelVoxel[], cor: [] as LabelVoxel[], sag: [] as LabelVoxel[] };
COMPS.forEach((g, i) => {
  for (const v of g) {
    // Display: axial cols i, rows ny-1-j; coronal cols i, rows nz-1-k; sagittal cols ny-1-j, rows nz-1-k.
    if (v[2] === raw.axialK) labels.ax.push([v[0], NY - 1 - v[1], i + 1]);
    if (v[1] === raw.coronalJ) labels.cor.push([v[0], NZ - 1 - v[2], i + 1]);
    if (v[0] === raw.sagittalI) labels.sag.push([NY - 1 - v[1], NZ - 1 - v[2], i + 1]);
  }
});

export const LESION = {
  source: raw.source,
  grid: raw.grid as { dims: number[]; spacing: number[]; origin: number[] },
  /** Axial grid slice of the primary; z = k + origin. */
  k: raw.axialK,
  z: raw.axialK + ORIGIN[2],
  /** Grid k of a display slice and back. */
  zOfK: (k: number) => k + ORIGIN[2],
  mask: MASK as readonly Voxel3[],
  components: COMPS as readonly (readonly Voxel3[])[],
  rows: ROWS,
  current: CURRENT,
  images: { ax: image('ax_flair'), cor: image('cor_flair'), sag: image('sag_flair') },
  coronalJ: raw.coronalJ,
  sagittalI: raw.sagittalI,
  /** Lesion voxels on the rendered slices, labelled by row id, display coords. */
  labels,
  crop: raw.crop as { c0: number; r0: number; size: number; values: number[] },
  histogram: raw.histogram as { bins: number[]; max: number },
};

/** FLAIR intensity (0–255) at an axial display voxel, inside the generator's crop; null outside it. */
export function flairAt(c: number, r: number): number | null {
  const { c0, r0, size, values } = LESION.crop;
  const x = c - c0;
  const y = r - r0;
  if (x < 0 || y < 0 || x >= size || y >= size) return null;
  return values[y * size + x];
}

/** Lesions crossing an axial grid slice k (the slice ruler). */
export function lesionsOnK(k: number): Lesion[] {
  return ROWS.filter((r) => r.k[0] <= k && k <= r.k[1]);
}
